const s=$json; const prompt="You are planning the slides (between 4 and 7 slides) of a social carousel for WE, HUMANITY, a reverent but not stuffy series about human creativity, design and craftsmanship.

Story title: {{title}}
Pillar: {{pillar}}
Glance: {{glance}}
Explore: {{explore}}
Deep dive: {{deep_dive}}
Remember: {{remember}}

Rules:
- Between 4 and 7 slides: choose the count that best fits the story's distinct visual beats without padding. Slide 1 is the cover; the final slide carries the Remember line.
- For Slide 1 (cover), pick a BRIGHT, ICONIC, IMMEDIATELY RECOGNIZABLE subject (e.g. a clear shaft opening, tunnel entrance, close-up of the artifact/object, or portrait) — NEVER a dark, muddy, or generic landscape texture.
- For each slide, name the REAL subject to photograph: a specific object, person, place, or drawing that exists and can be found in a museum or photo archive (e.g. "Bialetti Moka Express stovetop coffee maker, 1933 model"). Do not invent products, models, or variants. If no concrete real subject fits, use "abstract" and explain in `note`.
- Give 2–3 `search_queries` that would find that exact subject on Wikimedia Commons (short, specific, English).
- Do not invent facts. Do not write slide text or captions.
- Flag anything you are unsure exists as `"verify": true`.

Return ONLY JSON in this shape:
{"slides":[{"slide_index":1,"slide_type":"cover|object|person|process|detail|remember","subject":"...","search_queries":["...","..."],"note":"","verify":false}, ... 4 to 7 items]}
";return [{json:{...s,planningPrompt:prompt.replace("{{title}}",s.Title).replace("{{pillar}}",s.Pillar).replace("{{glance}}",s.Glance).replace("{{explore}}",s.Explore).replace("{{deep_dive}}",s["Deep Dive"]).replace("{{remember}}",s.Remember)}}];

const x=$input.first().json;
let p=x;
if(!Array.isArray(x)&&!x.slides){
const raw=(x.content?.parts?.map(p=>p.text||"").join("")||x.text||x.output||"").replace(/```(?:json)?/g,"").trim();
p=JSON.parse(raw);
}
const slides=Array.isArray(p)?p:p.slides;
if(!Array.isArray(slides)||slides.length<4||slides.length>7)throw new Error("Invalid slide plan: expected 4 to 7 slides");
const seen=new Set();
return slides.map((s,i)=>{if(!Number.isInteger(s.slide_index)||s.slide_index<1||s.slide_index>slides.length||seen.has(s.slide_index)||!s.subject||!s.slide_type||!Array.isArray(s.search_queries)||s.search_queries.length<2||s.search_queries.length>3||s.search_queries.some(q=>typeof q!=="string"||!q.trim()))throw new Error("Invalid slide plan entry "+(i+1));seen.add(s.slide_index);return {json:s,pairedItem:{item:0}};});

// Descriptor words such as "detail" or "controls" make Commons search return
// unrelated files, so drop them and de-duplicate the remaining queries.
const GENERIC = new Set(['detail','details','closeup','close-up','close','view','angle','shot','photo','photograph','image','controls','knobs','tonearm','macro','background']);
return $input.all().flatMap((x, i) => {
  const seen = new Set();
  const queries = [];
  for (const q of x.json.search_queries || []) {
    const cleaned = String(q).split(/\s+/).filter((wd) => wd && !GENERIC.has(wd.toLowerCase())).join(' ').trim();
    const key = cleaned.toLowerCase();
    if (cleaned && !seen.has(key)) { seen.add(key); queries.push(cleaned); }
  }
  return queries.map((query) => ({ json: { ...x.json, query }, pairedItem: { item: i } }));
});

// Deterministic licence filter and Commons response parser for WF3c.
// Pure functions: no network, no model calls.
// For n8n: paste the function bodies only. Delete the "LOCAL TEST ONLY" line at the bottom.

// Normalise a licence short name from Commons (LicenseShortName / License).
// Returns the canonical licence label, or null if not allowed.
function normaliseLicence(raw) {
  if (!raw || typeof raw !== 'string') return null;
  const s = raw.trim().toLowerCase().replace(/\s+/g, ' ');
  if (s === 'public domain' || s.startsWith('pd-') || s === 'pd') return 'Public domain';
  if (s === 'cc0' || s.startsWith('cc0 ') || s.startsWith('cc0-')) return 'CC0';
  if (/^cc[ -]by[ -]sa\b/.test(s) && !/-(nc|nd)\b/.test(s)) return 'CC BY-SA';
  if (/^cc[ -]by\b/.test(s) && !/-(nc|nd|sa)\b/.test(s)) return 'CC BY';
  return null;
}

// Parse a Commons imageinfo API page into a normalised candidate.
function parseCommonsPage(page) {
  const info = page && page.imageinfo && page.imageinfo[0];
  if (!info) return { ok: false, reason: 'no imageinfo' };
  const meta = info.extmetadata || {};
  const val = (k) => (meta[k] && meta[k].value ? String(meta[k].value) : '');
  const stripHtml = (s) => String(s || '').replace(/<[^>]*>/g, '')
    .replace(/&(amp|quot|apos|nbsp|lt|gt);|&#(x[0-9a-f]+|[0-9]+);/gi, (m, name, code) => {
      if (name) return {amp:'&',quot:'"',apos: String.fromCharCode(39),nbsp:' ',lt:'<',gt:'>'}[name.toLowerCase()];
      const n = code[0].toLowerCase() === 'x' ? parseInt(code.slice(1),16) : parseInt(code,10);
      return n >= 0 && n <= 0x10ffff ? String.fromCodePoint(n) : m;
    }).replace(/\s+/g, ' ').trim();
  const licenceRaw = val('LicenseShortName') || val('License');
  const mime = info.mime || '';
  return {
    ok: true,
    pageid: page.pageid,
    title: page.title || '',
    pageUrl: info.descriptionurl || '',
    downloadUrl: info.thumburl || info.url || '',
    originalUrl: info.url || '',
    width: info.width || null,
    height: info.height || null,
    mime,
    isImage: /^image\/(jpeg|png|tiff|webp)$/.test(mime),
    licence: normaliseLicence(licenceRaw),
    licenceRaw,
    licenseUrl: val('LicenseUrl'),
    artist: stripHtml(val('Artist')),
    credit: stripHtml(val('Credit')),
    description: stripHtml(val('ImageDescription')),
    dateCreated: stripHtml(val('DateTimeOriginal') || val('DateTime') || ''),
    usageTerms: stripHtml(val('UsageTerms')),
  };
}

// Decide whether a candidate is acceptable under the project's rules.
function filterCandidate(c) {
  const reasons = [];
  if (!c || !c.ok) reasons.push('unparseable');
  else {
    if (!c.isImage) reasons.push('not a supported image type: ' + c.mime);
    if (!c.licence) reasons.push('licence not allowed: ' + (c.licenceRaw || 'unknown'));
    if (!c.pageUrl) reasons.push('missing source page URL');
    if (!c.downloadUrl) reasons.push('missing download URL');
    if (c.width && c.width < 800) reasons.push('too small (' + c.width + 'px wide)');
    if (c.height && c.height < 600) reasons.push('too short (' + c.height + 'px tall)');
    if (c.width && c.height) {
      const aspect = c.width / c.height;
      if (aspect > 2.2 || aspect < 0.35) reasons.push('extreme aspect ratio (' + c.width + 'x' + c.height + ')');
    }
  }
  return { pass: reasons.length === 0, reasons };
}

// Filter and rank candidates. CC0/PD first, then CC BY, then CC BY-SA; wider first within a tier.
function filterAndRank(candidates) {
  const rank = { 'CC0': 0, 'Public domain': 0, 'CC BY': 1, 'CC BY-SA': 2 };
  return candidates
    .map((c) => ({ c, f: filterCandidate(c) }))
    .filter((x) => x.f.pass)
    .sort((a, b) => (rank[a.c.licence] - rank[b.c.licence]) || ((b.c.width || 0) - (a.c.width || 0)))
    .map((x) => x.c);
}

// Full attribution string. CC BY / CC BY-SA need: title, author, licence name + link,
// Commons page, and an indication of changes. Store in Assets Credit and show on the slide.
// Deterministic; never generated by the model.
function buildCredit(c) {
  if (!c) return '';
  const artist = c.artist && c.artist !== 'Unknown' ? c.artist : 'Unknown author';
  const title = (c.title || '').replace(/^File:/, '').replace(/_/g, ' ');
  if (c.licence === 'CC BY' || c.licence === 'CC BY-SA') {
    const link = c.licenseUrl ? ' (' + c.licenseUrl + ')' : '';
    return '"' + title + '" by ' + artist + ' via Wikimedia Commons (' + c.pageUrl + '), licensed under ' + (c.licenceRaw || c.licence) + link + '. Cropped and resized; no other changes.';
  }
  if (c.licence === 'CC0') {
    return '"' + title + '" by ' + artist + ', CC0 (public domain dedication), via Wikimedia Commons (' + c.pageUrl + ').';
  }
  return '"' + title + '" by ' + artist + ', public domain, via Wikimedia Commons (' + c.pageUrl + ').';
}


// Rank by relevance to this slide's own words, then licence, then width.
// The old order was licence first, so public-domain scans outranked the real
// subject and slice(0,5) then discarded the correct CC BY / CC BY-SA photos.
const STOP = new Set(['the','and','of','for','with','by','designed','a','an','in','on','at','from','to','its','his','her','their']);
function slideTokens(slide) {
  const text = [slide.subject || '', ...(slide.search_queries || [])].join(' ').toLowerCase();
  const out = new Set();
  for (const w of text.split(/[^a-z0-9]+/).filter(Boolean)) {
    if (w.length >= 3 && !STOP.has(w)) out.add(w);
    else if (/[a-z]/.test(w) && /[0-9]/.test(w)) out.add(w);
  }
  return [...out];
}
const squash = (v) => String(v || '').toLowerCase().replace(/[^a-z0-9]+/g, '');
const wordsOf = (v) => new Set(String(v || '').toLowerCase().split(/[^a-z0-9]+/).filter(Boolean));
// Plain words must match a whole word (so 'braun' does not match 'Braunerova').
// Tokens containing a digit (sk4, et66, 606) match inside the squashed string,
// because titles write them as 'SK 4' or 'Vitsoe606'.
function relevance(c, tokens) {
  const text = c.title + ' ' + c.description;
  const words = wordsOf(text);
  const hay = squash(text);
  let n = 0;
  for (const t of tokens) {
    if (/[0-9]/.test(t)) { if (hay.includes(t)) n++; }
    else if (words.has(t)) n++;
  }
  return n;
}
function rankForSlide(candidates, tokens) {
  const licenceRank = { 'CC0': 0, 'Public domain': 0, 'CC BY': 1, 'CC BY-SA': 2 };
  const scored = candidates.map((c) => ({ c, hits: relevance(c, tokens) }));
  const best = scored.reduce((m, x) => Math.max(m, x.hits), 0);
  const keep = best > 0 ? scored.filter((x) => x.hits > 0) : scored;
  return keep
    .sort((a, b) => (b.hits - a.hits)
      || ((b.c.width || 0) - (a.c.width || 0))
      || (licenceRank[a.c.licence] - licenceRank[b.c.licence]))
    .map((x) => x.c);
}

const groups = new Map();
const qs = $('Expand Queries').all();
for (const [i, r] of $input.all().entries()) {
  const m = qs[i].json;
  let g = groups.get(m.slide_index);
