  for (const p of Object.values(r.json.query?.pages || {})) g.pages.set(p.pageid, { ...p, foundQuery: m.query });
}
return [...groups.values()].map((g) => {
  const usable = [...g.pages.values()]
    .map((p) => ({ ...parseCommonsPage(p), foundQuery: p.foundQuery }))
    .filter((c) => c.ok
      && !/\b(?:NC|ND)\b/i.test(c.licenceRaw)
      && c.downloadUrl.startsWith('https://')
      && /^https:\/\/(?:upload|thumb)\.wikimedia\.org\//.test(c.downloadUrl)
      && c.pageUrl.startsWith('https://commons.wikimedia.org/'))
    .filter((c) => filterCandidate(c).pass);
  const candidates = rankForSlide(usable, slideTokens(g)).slice(0, 5);
  const { pages, ...slide } = g;
  return { json: { ...slide, candidates, researchStatus: candidates.length ? 'ready' : 'no_candidates' }, pairedItem: { item: 0 } };
});

