const base=$('Prepare Batch Choice').first().json.slides;
const parsed=parse($input.first().json);
const choiceList=Array.isArray(parsed.choices)?parsed.choices:[parsed];
const bySlide=new Map(choiceList.map(c=>[Number(c.slide_index),c]));
const used=new Map();
return base.map((s,i)=>{
  const c=bySlide.get(Number(s.slide_index))||choiceList[i]||{chosen_pageid:null,confidence:'low',reason:'No decision returned.'};
  const skip=s.subject.toLowerCase()==='abstract';
  const chosen=(s.candidates||[]).find(z=>String(z.pageid)===String(c.chosen_pageid));
  let pick=null,dupOf=null;
  if(!skip&&chosen&&c.confidence!=='low'){
    if(!used.has(chosen.pageid)){ pick=chosen; }
    else {
      dupOf=used.get(chosen.pageid);
      pick=(s.candidates||[]).find(z=>!used.has(z.pageid))||null;
    }
    if(pick) used.set(pick.pageid, s.slide_index);
  }
  const ok=!skip&&!s.verify&&pick&&String(pick.pageid)===String(c.chosen_pageid)&&c.confidence==='high';
  const reason=[String(c.reason||''),dupOf?('Same image as slide '+dupOf+', so the next unused candidate from the pool was taken.'):''].filter(Boolean).join(' ');
  const aiFallbackPrompt=(!skip&&!pick)?['Archival museum documentary photograph of '+(s.subject||'historical design object')+'.','Soft diffuse museum gallery lighting, neutral off-white matte background, gentle natural cast shadows.','Shot on medium format camera, 80mm lens, f/8 aperture, razor-sharp optical focus, natural fine film grain.','No text, no logos, no modern accessories, no CGI render look.'].join(' '):'';
  return {json:{...s,chosen:pick,confidence:c.confidence,reason,duplicate_of:dupOf,aiFallbackPrompt,result:skip?'text_only':ok?'selected':pick?'needs_review':dupOf?'duplicate':'no_image'},pairedItem:{item:0}};
});

