    .map((c) => ({ c, f: filterCandidate(c) }))
    .filter((x) => x.f.pass)
    .sort((a, b) => (rank[a.c.licence] - rank[b.c.licence]) || ((b.c.width || 0) - (a.c.width || 0)))
    .map((x) => x.c);
