// Normalise an Openverse license code (cc0, pdm, by, by-sa) to canonical label, or null if disallowed.
function normaliseOpenverseLicence(lic) {
  if (!lic || typeof lic !== 'string') return null;
  const l = lic.trim().toLowerCase();
  if (l === 'cc0') return 'CC0';
  if (l === 'pdm' || l === 'public domain') return 'Public domain';
  if (l === 'by') return 'CC BY';
  if (l === 'by-sa') return 'CC BY-SA';
  return null;
}

// Parse an Openverse v1 /images/ result into the normalised candidate schema.
function parseOpenversePage(item) {
  if (!item || !item.id) return { ok: false, reason: 'invalid item payload' };
  const licence = normaliseOpenverseLicence(item.license);
  const mime = item.filetype ? 'image/' + String(item.filetype).toLowerCase().replace(/^jpg$/, 'jpeg') : 'image/jpeg';
  const rawLicence = item.license
    ? (licence === 'Public domain' ? 'Public domain' : licence === 'CC0' ? 'CC0' : ('CC ' + String(item.license).toUpperCase() + ' ' + (item.license_version || '')).trim())
    : '';
  return {
    ok: true,
    pageid: item.id,
    title: item.title || 'Untitled',
    pageUrl: item.foreign_landing_url || item.url || '',
    downloadUrl: item.url || '',
    originalUrl: item.url || '',
    thumbnailUrl: item.thumbnail || '',
    width: item.width || 1200,
    height: item.height || null,
    mime,
    isImage: /^image\/(jpeg|png|tiff|webp)$/.test(mime),
    licence,
    licenceRaw: rawLicence,
    licenseUrl: item.license_url || '',
    artist: item.creator || 'Unknown author',
    credit: item.attribution || '',
    description: (item.title || '') + (Array.isArray(item.tags) ? ' ' + item.tags.map((t) => t.name).filter(Boolean).join(' ') : ''),
    dateCreated: '',
    usageTerms: '',
    sourceProvider: item.source || 'Openverse',
    tier: 'Tier 2: Openverse',
  };
}

// Deterministic attribution string for Openverse candidates.
function buildOpenverseCredit(c) {
  if (!c) return '';
  const artist = c.artist && c.artist !== 'Unknown' ? c.artist : 'Unknown author';
  const title = (c.title || 'Untitled').replace(/"/g, "'");
  const source = c.sourceProvider || 'Openverse';
  if (c.licence === 'CC BY' || c.licence === 'CC BY-SA') {
    const link = c.licenseUrl ? ' (' + c.licenseUrl + ')' : '';
    return '"' + title + '" by ' + artist + ' via ' + source + ' (' + c.pageUrl + '), licensed under ' + (c.licenceRaw || c.licence) + link + '. Cropped and resized; no other changes.';
  }
  if (c.licence === 'CC0') {
